use shapes::{norm, Point};

fn square(x: i32) -> i32 {
    x * x
}

fn main() {
    let v: Vec<i32> = (1..=10).map(square).collect();
    let total: i32 = v.iter().sum();
    println!("{total} {}", norm(Point { x: 3.0, y: 4.0 }));
}

